import unittest
from candidate import triangle_area

class TestTriangleArea(unittest.TestCase):
    def test_triangle_area_positive_integers(self):
        self.assertEqual(triangle_area(4, 5), 10.0)

    def test_triangle_area_positive_floats(self):
        self.assertAlmostEqual(triangle_area(3.5, 2.0), 3.5)

    def test_triangle_area_zero_base(self):
        self.assertEqual(triangle_area(0, 5), 0.0)

    def test_triangle_area_zero_height(self):
        self.assertEqual(triangle_area(4, 0), 0.0)

    def test_triangle_area_negative_values(self):
        self.assertEqual(triangle_area(-3, 4), -6.0)

    def test_triangle_area_large_numbers(self):
        self.assertAlmostEqual(triangle_area(1e6, 1e6), 5e11)

    def test_triangle_area_none_base(self):
        with self.assertRaises(TypeError):
            triangle_area(None, 5)

    def test_triangle_area_none_height(self):
        with self.assertRaises(TypeError):
            triangle_area(4, None)

    def test_triangle_area_string_input(self):
        with self.assertRaises(TypeError):
            triangle_area("4", 5)

    def test_triangle_area_empty_list_input(self):
        with self.assertRaises(TypeError):
            triangle_area([], 5)

    def test_triangle_area_missing_arguments(self):
        with self.assertRaises(TypeError):
            triangle_area()

if __name__ == '__main__':
    unittest.main()
